from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <algorithm>
__device__ __forceinline__ void blockReduceSum2(double &s, double &q,
                                                double *shS, double *shQ) {
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int nwarps = (blockDim.x + 31) >> 5;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        s += __shfl_down_sync(0xffffffffu, s, off);
        q += __shfl_down_sync(0xffffffffu, q, off);
    }
    if (lane == 0) {
        shS[warp] = s;
        shQ[warp] = q;
    }
    __syncthreads();
    if (warp == 0) {
        s = (lane < nwarps) ? shS[lane] : 0.0;
        q = (lane < nwarps) ? shQ[lane] : 0.0;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            s += __shfl_down_sync(0xffffffffu, s, off);
            q += __shfl_down_sync(0xffffffffu, q, off);
        }
    }
}
// Phase 1 kernel: partial sum / sum-of-squares per row chunk, folded into
// per-row global totals with double-precision atomicAdd. This removes the
// cooperative launch and the expensive grid.sync() global barrier: the
// cross-block synchronization is provided by the kernel boundary, so both
// kernels can use a freely sized grid (not limited to co-resident blocks)
// and reach full occupancy with normal, low-overhead launches.
__global__ void layernorm_reduce_kernel(const float *__restrict__ x,
                                        double *__restrict__ psum,
                                        double *__restrict__ psq,
                                        int rows, long long n,
                                        int blocksPerRow) {
    __shared__ double shS[32];
    __shared__ double shQ[32];
    const int row = blockIdx.x % rows;
    const int part = blockIdx.x / rows;
    const float *xr = x + (long long)row * n;
    const bool vec4 = ((n & 3) == 0);
    const long long nv = vec4 ? (n >> 2) : n;
    const long long chunk = (nv + blocksPerRow - 1) / blocksPerRow;
    const long long start = (long long)part * chunk;
    const long long end = min(nv, start + chunk);
    // Unroll by 2 with independent accumulators: breaks the serial
    // dependency chain on the double-precision accumulators and doubles
    // memory-level parallelism per thread (two independent 16B loads in
    // flight), which lifts achieved streaming bandwidth.
    double s0 = 0.0, q0 = 0.0, s1 = 0.0, q1 = 0.0;
    const long long stride = blockDim.x;
    long long i = start + threadIdx.x;
    if (vec4) {
        const float4 *x4 = reinterpret_cast<const float4 *>(xr);
        for (; i + stride < end; i += 2 * stride) {
            float4 v0 = __ldcs(&x4[i]);
            float4 v1 = __ldcs(&x4[i + stride]);
            s0 += (double)v0.x + (double)v0.y + (double)v0.z + (double)v0.w;
            q0 += (double)v0.x * v0.x + (double)v0.y * v0.y +
                  (double)v0.z * v0.z + (double)v0.w * v0.w;
            s1 += (double)v1.x + (double)v1.y + (double)v1.z + (double)v1.w;
            q1 += (double)v1.x * v1.x + (double)v1.y * v1.y +
                  (double)v1.z * v1.z + (double)v1.w * v1.w;
        }
        if (i < end) {
            float4 v = __ldcs(&x4[i]);
            s0 += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
            q0 += (double)v.x * v.x + (double)v.y * v.y +
                  (double)v.z * v.z + (double)v.w * v.w;
        }
    } else {
        for (; i + stride < end; i += 2 * stride) {
            double v0 = (double)__ldcs(&xr[i]);
            double v1 = (double)__ldcs(&xr[i + stride]);
            s0 += v0;
            q0 += v0 * v0;
            s1 += v1;
            q1 += v1 * v1;
        }
        if (i < end) {
            double v = (double)__ldcs(&xr[i]);
            s0 += v;
            q0 += v * v;
        }
    }
    double s = s0 + s1, q = q0 + q1;
    blockReduceSum2(s, q, shS, shQ);
    if (threadIdx.x == 0) {
        atomicAdd(&psum[row], s);
        atomicAdd(&psq[row], q);
    }
}
