// row mean / rstd from the finalized per-row totals (two double loads),
// which is negligible compared to the streaming work.
__global__ void layernorm_normalize_kernel(const float *__restrict__ x,
                                           const float *__restrict__ w,
                                           const float *__restrict__ b,
                                           float *__restrict__ y,
                                           const double *__restrict__ psum,
                                           const double *__restrict__ psq,
                                           int rows, long long n,
                                           int blocksPerRow, float eps) {
