    __shared__ double shRstd;
    const int row = blockIdx.x % rows;
    const int part = blockIdx.x / rows;
    const float *xr = x + (long long)row * n;
    float *yr = y + (long long)row * n;
    const bool vec4 = ((n & 3) == 0);
    const long long nv = vec4 ? (n >> 2) : n;
    const long long chunk = (nv + blocksPerRow - 1) / blocksPerRow;
    const long long start = (long long)part * chunk;
    const long long end = min(nv, start + chunk);
    if (threadIdx.x == 0) {
        double mean = psum[row] / (double)n;
        double var = psq[row] / (double)n - mean * mean;
        if (var < 0.0) var = 0.0;
        shMean = mean;
        shRstd = rsqrt(var + (double)eps);
    }
    __syncthreads();
    const double mean = shMean;
    const double rstd = shRstd;
    if (vec4) {
        const float4 *x4 = reinterpret_cast<const float4 *>(xr);
        const float4 *w4 = reinterpret_cast<const float4 *>(w);
        const float4 *b4 = reinterpret_cast<const float4 *>(b);
        float4 *y4 = reinterpret_cast<float4 *>(yr);
        const long long stride = blockDim.x;
        long long i = start + threadIdx.x;
        for (; i + stride < end; i += 2 * stride) {
            float4 xv0 = __ldcs(&x4[i]);
            float4 wv0 = w4[i];
            float4 bv0 = b4[i];
            float4 xv1 = __ldcs(&x4[i + stride]);
            float4 wv1 = w4[i + stride];
            float4 bv1 = b4[i + stride];
            float4 o0, o1;
            o0.x = (float)(((double)xv0.x - mean) * rstd) * wv0.x + bv0.x;
            o0.y = (float)(((double)xv0.y - mean) * rstd) * wv0.y + bv0.y;
            o0.z = (float)(((double)xv0.z - mean) * rstd) * wv0.z + bv0.z;
            o0.w = (float)(((double)xv0.w - mean) * rstd) * wv0.w + bv0.w;
            o1.x = (float)(((double)xv1.x - mean) * rstd) * wv1.x + bv1.x;
            o1.y = (float)(((double)xv1.y - mean) * rstd) * wv1.y + bv1.y;
            o1.z = (float)(((double)xv1.z - mean) * rstd) * wv1.z + bv1.z;
            o1.w = (float)(((double)xv1.w - mean) * rstd) * wv1.w + bv1.w;
            __stcs(&y4[i], o0);
            __stcs(&y4[i + stride], o1);
        }
        if (i < end) {
            float4 xv = __ldcs(&x4[i]);
            float4 wv = w4[i];
            float4 bv = b4[i];
            float4 o;
            o.x = (float)(((double)xv.x - mean) * rstd) * wv.x + bv.x;
            o.y = (float)(((double)xv.y - mean) * rstd) * wv.y + bv.y;
            o.z = (float)(((double)xv.z - mean) * rstd) * wv.z + bv.z;
            o.w = (float)(((double)xv.w - mean) * rstd) * wv.w + bv.w;
            __stcs(&y4[i], o);
        }
    } else {
        const long long stride = blockDim.x;
        long long i = start + threadIdx.x;
        for (; i + stride < end; i += 2 * stride) {
            float v0 = (float)(((double)__ldcs(&xr[i]) - mean) * rstd);
            float v1 = (float)(((double)__ldcs(&xr[i + stride]) - mean) * rstd);
            __stcs(&yr[i], v0 * w[i] + b[i]);
            __stcs(&yr[i + stride], v1 * w[i + stride] + b[i + stride]);
        }
        if (i < end) {
            float v = (float)(((double)__ldcs(&xr[i]) - mean) * rstd);
            __stcs(&yr[i], v * w[i] + b[i]);
        }
    }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight,
                                torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    auto bc = bias.contiguous();
    const long long n = (long long)wc.numel();
    const long long total = (long long)xc.numel();
    TORCH_CHECK(n > 0 && total % n == 0, "normalized shape mismatch");
    int rows = (int)(total / n);
    auto y = at::empty_like(xc);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    int dev = (int)xc.get_device();
    const int block = 256;
    int perSm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &perSm, (void *)layernorm_reduce_kernel, block, 0);
    TORCH_CHECK(perSm > 0, "occupancy query failed");
    int smcount = 0;
    cudaDeviceGetAttribute(&smcount, cudaDevAttrMultiProcessorCount, dev);
    const long long maxBlocks = (long long)perSm * smcount;
    const long long nv = ((n & 3) == 0) ? (n >> 2) : n;
    const long long want = (nv + block - 1) / block;
    int blocksPerRow = (int)std::min<long long>(
        std::min<long long>((2LL * maxBlocks) / rows, want), 256LL);
    if (blocksPerRow < 1) blocksPerRow = 1;
    const int grid = rows * blocksPerRow;
    auto ws = at::zeros({2LL * rows}, xc.options().dtype(at::kDouble));
    double *psum = ws.data_ptr<double>();
    double *psq = psum + rows;
    layernorm_reduce_kernel<<<grid, block, 0, stream>>>(
        xc.data_ptr<float>(), psum, psq, rows, n, blocksPerRow);
    C10_CUDA_CHECK(cudaGetLastError());
    layernorm_normalize_kernel<<<grid, block, 0, stream>>>(
        xc.data_ptr<float>(), wc.data_ptr<float>(), bc.data_ptr<float>(),
        y.data_ptr<float>(), psum, psq, rows, n, blocksPerRow, (float)eps);
    C10_CUDA_CHECK(cudaGetLastError());
    return y;
}
"""

cpp_src = "torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);"

_mod = load_inline(
    name="layernorm_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single fused custom CUDA kernel.
    """

    def __init__(self, normalized_shape) -> None:
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.layernorm_forward(x, self.weight, self.bias, self.eps)

